    private const int MaximumMetadataLength = 16 * 1024;

    public async Task RecordAsync(ActivityEvent activityEvent, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(activityEvent);
        ActivityPreferences preferences = await GetPreferencesAsync(cancellationToken).ConfigureAwait(false);
        if (!ShouldRecord(activityEvent, preferences.HistoryMode)) return;
        string? metadata = activityEvent.MetadataJson;
        if (metadata?.Length > MaximumMetadataLength) throw new InvalidOperationException("Activity metadata exceeds the local safety limit.");
        DateTime created = activityEvent.CreatedAtUtc == default ? DateTime.UtcNow : activityEvent.CreatedAtUtc.ToUniversalTime();
        await using SqliteConnection c = await factory.OpenAsync(cancellationToken).ConfigureAwait(false);
        await using SqliteCommand cmd = c.CreateCommand();
        cmd.CommandText = "INSERT OR IGNORE INTO ActivityEvents(Id,EventType,TargetType,TargetId,SessionId,TitleSnapshot,SubtitleSnapshot,ProviderId,PlatformId,OccurredAtUtc,EndedAtUtc,DurationSeconds,Result,PrivacyLevel,GuestSessionId,MetadataJson,CorrelationId,CreatedAtUtc) VALUES($id,$type,$targetType,$target,$session,$title,$subtitle,$provider,$platform,$occurred,$ended,$duration,$result,$privacy,$guest,$metadata,$correlation,$created);";
        Add(cmd,"$id",activityEvent.Id); Add(cmd,"$type",(int)activityEvent.EventType); Add(cmd,"$targetType",(int)activityEvent.TargetType); Add(cmd,"$target",Db(activityEvent.TargetId)); Add(cmd,"$session",Db(activityEvent.SessionId)); Add(cmd,"$title",Db(Bound(activityEvent.TitleSnapshot,256))); Add(cmd,"$subtitle",Db(Bound(activityEvent.SubtitleSnapshot,256))); Add(cmd,"$provider",Db(Bound(activityEvent.ProviderId,80))); Add(cmd,"$platform",Db(Bound(activityEvent.PlatformId,80))); Add(cmd,"$occurred",Iso(activityEvent.OccurredAtUtc)); Add(cmd,"$ended",Db(activityEvent.EndedAtUtc is null?null:Iso(activityEvent.EndedAtUtc.Value))); Add(cmd,"$duration",activityEvent.DurationSeconds is null?DBNull.Value:Math.Max(0,activityEvent.DurationSeconds.Value)); Add(cmd,"$result",(int)activityEvent.Result); Add(cmd,"$privacy",(int)activityEvent.PrivacyLevel); Add(cmd,"$guest",Db(activityEvent.GuestSessionId)); Add(cmd,"$metadata",Db(metadata)); Add(cmd,"$correlation",Db(activityEvent.CorrelationId)); Add(cmd,"$created",Iso(created));
        await cmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    public async Task<IReadOnlyList<ActivityEvent>> QueryAsync(ActivityQuery query, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(query); int maximum=Math.Clamp(query.MaximumResults,1,500);int offset=Math.Max(0,query.Offset);
        StringBuilder sql=new("SELECT Id,EventType,TargetType,TargetId,SessionId,TitleSnapshot,SubtitleSnapshot,ProviderId,PlatformId,OccurredAtUtc,EndedAtUtc,DurationSeconds,Result,PrivacyLevel,GuestSessionId,MetadataJson,CorrelationId,CreatedAtUtc FROM ActivityEvents WHERE 1=1");
        await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteCommand cmd=c.CreateCommand();
        if(!query.IncludePrivate)sql.Append(" AND PrivacyLevel<>1");if(!query.IncludeGuest)sql.Append(" AND PrivacyLevel<>2");if(!query.IncludeHidden)sql.Append(" AND PrivacyLevel<>3");
        if(query.TargetId is not null){sql.Append(" AND TargetId=$target");Add(cmd,"$target",query.TargetId);}if(query.ProviderId is not null){sql.Append(" AND ProviderId=$provider");Add(cmd,"$provider",query.ProviderId);}if(query.PlatformId is not null){sql.Append(" AND PlatformId=$platform");Add(cmd,"$platform",query.PlatformId);}
        if(query.FromUtc is not null){sql.Append(" AND OccurredAtUtc>=$from");Add(cmd,"$from",Iso(query.FromUtc.Value));}if(query.ToUtc is not null){sql.Append(" AND OccurredAtUtc<$to");Add(cmd,"$to",Iso(query.ToUtc.Value));}
        if(query.EventTypes is {Count:>0}){string[] names=query.EventTypes.Select((_,i)=>"$event"+i).ToArray();sql.Append(" AND EventType IN ("+string.Join(',',names)+")");int i=0;foreach(ActivityEventType type in query.EventTypes)Add(cmd,names[i++],(int)type);}
        sql.Append(" ORDER BY OccurredAtUtc DESC,Id DESC LIMIT $max OFFSET $offset;");Add(cmd,"$max",maximum);Add(cmd,"$offset",offset);cmd.CommandText=sql.ToString();
        List<ActivityEvent> result=[];await using SqliteDataReader r=await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);while(await r.ReadAsync(cancellationToken).ConfigureAwait(false))result.Add(ReadActivity(r));return result;
    }

    public Task DeleteAsync(string activityEventId,CancellationToken cancellationToken=default)=>ExecuteAsync("DELETE FROM ActivityEvents WHERE Id=$id;",[("$id",activityEventId)],cancellationToken);
    public async Task ClearAsync(ActivityClearRequest request,CancellationToken cancellationToken=default)
    {
        ArgumentNullException.ThrowIfNull(request);if(!request.ClearAll&&request.TargetId is null&&request.EventType is null&&!request.GuestOnly)throw new InvalidOperationException("A bounded activity clear request is required.");
        StringBuilder sql=new("DELETE FROM ActivityEvents WHERE 1=1");List<(string,object)> args=[];if(!request.IncludePrivate)sql.Append(" AND PrivacyLevel<>1");if(request.TargetId is not null){sql.Append(" AND TargetId=$target");args.Add(("$target",request.TargetId));}if(request.EventType is not null){sql.Append(" AND EventType=$type");args.Add(("$type",(int)request.EventType.Value));}if(request.GuestOnly)sql.Append(" AND PrivacyLevel=2");await ExecuteAsync(sql.Append(';').ToString(),args,cancellationToken).ConfigureAwait(false);
