    public async Task<ActivityRetentionResult> ApplyAsync(bool force=false,CancellationToken cancellationToken=default)
    {
        ActivityPreferences p=await GetPreferencesAsync(cancellationToken).ConfigureAwait(false);DateTime now=DateTime.UtcNow;if(!force&&p.LastRetentionAtUtc is not null&&now-p.LastRetentionAtUtc.Value<TimeSpan.FromDays(7))return new(0,false,now);
        int deleted=0;await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteTransaction tx=(SqliteTransaction)await c.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);
        await using(SqliteCommand cmd=c.CreateCommand()){cmd.Transaction=tx;cmd.CommandText="DELETE FROM ActivityEvents WHERE Id IN (SELECT Id FROM ActivityEvents WHERE OccurredAtUtc<$cutoff AND ($keepGames=0 OR EventType NOT IN (0,1)) AND ($keepCaptures=0 OR EventType<>5) AND ($keepArt=0 OR EventType<>9) ORDER BY OccurredAtUtc LIMIT 5000);";Add(cmd,"$cutoff",Iso(now.AddDays(-Math.Clamp(p.RetentionDays,1,3650))));Add(cmd,"$keepGames",p.KeepGameSessions?1:0);Add(cmd,"$keepCaptures",p.KeepCaptureEvents?1:0);Add(cmd,"$keepArt",p.KeepArtworkChanges?1:0);deleted+=await cmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}
        await using(SqliteCommand cmd=c.CreateCommand()){cmd.Transaction=tx;cmd.CommandText="DELETE FROM ActivityEvents WHERE Id IN (SELECT Id FROM ActivityEvents ORDER BY OccurredAtUtc DESC LIMIT -1 OFFSET $max);";Add(cmd,"$max",Math.Clamp(p.MaximumEventCount,100,100000));deleted+=await cmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}
        await using(SqliteCommand cmd=c.CreateCommand()){cmd.Transaction=tx;cmd.CommandText="UPDATE ActivityPreferences SET LastRetentionAtUtc=$at,UpdatedAtUtc=$at WHERE Id=1;";Add(cmd,"$at",Iso(now));await cmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}await tx.CommitAsync(cancellationToken).ConfigureAwait(false);return new(deleted,true,now);
    }

