    public async Task<IReadOnlyList<RemotePlayProfile>> GetAsync(CancellationToken cancellationToken=default)
    {await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText=RemoteSelect+" ORDER BY Name;";List<RemotePlayProfile> values=[];await using SqliteDataReader r=await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);while(await r.ReadAsync(cancellationToken).ConfigureAwait(false))values.Add(ReadRemote(r));return values;}
