public sealed class LocalActivityExportService(IActivityTimelineService timeline) : IActivityExportService
{
    private static readonly JsonSerializerOptions JsonOptions=new(){WriteIndented=true};
    public async Task ExportAsync(ActivityExportRequest request,CancellationToken cancellationToken=default)
    {
        ArgumentNullException.ThrowIfNull(request);string format=request.Format.Trim().ToLowerInvariant();if(format is not ("json" or "csv"))throw new InvalidOperationException("Activity exports support JSON or CSV.");string path=Path.GetFullPath(request.DestinationPath);string extension=Path.GetExtension(path).ToLowerInvariant();if(extension!=(format=="json"?".json":".csv"))throw new InvalidOperationException("The activity export extension does not match its format.");
        ActivityQuery query=request.Query with{IncludePrivate=request.IncludePrivate,MaximumResults=Math.Clamp(request.Query.MaximumResults,1,20_000)};IReadOnlyList<ActivityEvent> values=await timeline.QueryAsync(query,cancellationToken).ConfigureAwait(false);Directory.CreateDirectory(Path.GetDirectoryName(path)!);string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";
        try{if(format=="json"){object[] rows=values.Select(v=>(object)new{v.Id,Type=v.EventType.ToString(),Target=v.TargetType.ToString(),TargetId=v.TargetId,Title=request.IncludeTitles?v.TitleSnapshot:null,Provider=request.IncludeProvider?v.ProviderId:null,v.PlatformId,v.OccurredAtUtc,v.EndedAtUtc,DurationSeconds=request.IncludeDuration?v.DurationSeconds:null,Privacy=v.PrivacyLevel.ToString()}).ToArray();await File.WriteAllTextAsync(temp,JsonSerializer.Serialize(rows,JsonOptions),Encoding.UTF8,cancellationToken).ConfigureAwait(false);}else{StringBuilder b=new("Id,Type,Target,Title,Provider,OccurredAtUtc,DurationSeconds,Privacy\r\n");foreach(ActivityEvent v in values)b.Append(Csv(v.Id)).Append(',').Append(Csv(v.EventType.ToString())).Append(',').Append(Csv(v.TargetType.ToString())).Append(',').Append(Csv(request.IncludeTitles?v.TitleSnapshot:null)).Append(',').Append(Csv(request.IncludeProvider?v.ProviderId:null)).Append(',').Append(Csv(Iso(v.OccurredAtUtc))).Append(',').Append(request.IncludeDuration?v.DurationSeconds:null).Append(',').Append(Csv(v.PrivacyLevel.ToString())).Append("\r\n");await File.WriteAllTextAsync(temp,b.ToString(),Encoding.UTF8,cancellationToken).ConfigureAwait(false);}File.Move(temp,path,false);}finally{if(File.Exists(temp))File.Delete(temp);}
    }
    private static string Csv(string? value)=>'"'+(value??string.Empty).Replace("\"","\"\"")+'"';private static string Iso(DateTime value)=>value.ToUniversalTime().ToString("O",CultureInfo.InvariantCulture);
}
